import {useContext,useMemo as useIdentityMemo} from 'react';
import {EditorInteractionScope,useEditorBoundary} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useScopedControl,controlIdentity,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {timelineEditSignature} from '@/components/nyc-tron/ui/components/forge/timeline/timeline-identity';
import {useEffect,useRef} from "react";
import {Pressable,Text,TextInput,View,type DimensionValue,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {IconButton} from "@/components/nyc-tron/ui/components/IconButton";
import {useLocalStore} from "@/components/nyc-tron/ui/components/useLocalStore";
import {trackSilenced,type TimelineTrack,type TrackKind} from "@/components/nyc-tron/ui/components/forge/timeline/edits";
import {space,radius,border,size} from '@/components/nyc-tron/ui/tokens';
import {tokens} from '@/components/nyc-tron/ui/components/forge/timeline/TrackHeaders.tokens';

/** A track switch Splice stores (`setTrackFlags`). */
export type TrackFlag="locked"|"hidden"|"muted"|"solo";

/** Props for {@linkcode TrackHeaders}. */
export interface TrackHeadersProps extends Omit<ViewProps,"children">,ScopedControlProps {
  /** The same tracks, in the same order, as the lanes beside it. */
  readonly tracks:readonly TimelineTrack[];
  /** Match `TimelineClipLane` `laneHeight`. @default 56 */
  readonly laneHeight?:number;
  /** One call per toggle press. */
  readonly onSetFlag:(trackId:string,flag:TrackFlag,value:boolean)=>void;
  /** On Enter or blur with a changed, nonblank name. Escape restores the old one. */
  readonly onRename:(trackId:string,name:string)=>void;
  /** Move to `toIndex` in the host's track list (Splice `moveTrack`). */
  readonly onMove?:(trackId:string,toIndex:number)=>void;
  /**
   * Where a track goes when moved up (`-1`) or down (`1`). Defaults to its
   * neighbour in `tracks`; `OverlayAndEffectsTrackStack` keeps moves inside
   * a kind's group.
   */
  readonly moveTarget?:(trackId:string,direction:-1|1)=>number|undefined;
  /** Shows up/down buttons in place of the switches. */
  readonly reorder?:boolean;
  /** Header width. @default 232, or 56 when `compact` */
  readonly width?:DimensionValue;
  /**
   * Phone layout: each row is one 44pt button with the track's code (V1, O1,
   * A2) and its state, which calls `onOpenTrack`. The host shows that track's
   * full row elsewhere, as `OverlayAndEffectsTrackStack` does under the lanes.
   */
  readonly compact?:boolean;
  readonly openTrackId?:string;
  /** Every track, when `tracks` is a subset: solo on a track not shown still silences these. @default tracks */
  readonly allTracks?:readonly TimelineTrack[];
  readonly onOpenTrack?:(trackId:string|undefined)=>void;
  readonly disabled?:boolean;
  className?:string;
  unstyled?:boolean;
}

export const TRACK_KIND_LABEL:Readonly<Record<TrackKind,string>>={video:"Video",overlay:"Overlay",audio:"Audio"};
/** Which switches a kind of track has: hide on picture tracks, mute and solo on audio, lock on all. */
/** A short code per track: kind letter and position among tracks of that kind ("V1", "O2", "A1"). */
export function trackCode(track:TimelineTrack,tracks:readonly TimelineTrack[]):string{
  const same=tracks.filter(t=>t.kind===track.kind);
  return {video:"V",overlay:"O",audio:"A"}[track.kind]+(same.indexOf(track)+1);
}
export const trackFlags=(kind:TrackKind):readonly TrackFlag[]=>kind==="audio"?["locked","muted","solo"]:["locked","hidden"];

function LockGlyph({open,styled}:{open:boolean;styled:boolean}){
  const ink=styled?"border-text":"";
  return <View style={{alignItems:"center",width:16,height:18}}>
    <View {...{className:ink}} style={{width:10,height:8,borderWidth:border[2],borderBottomWidth:border[0],borderTopLeftRadius:radius[5],borderTopRightRadius:radius[5],
      marginLeft:open?space[2]:space[0]}}/>
    <View {...{className:styled?"bg-text":""}} style={{width:14,height:9,borderRadius:radius[2]}}/>
  </View>;
}
function EyeGlyph({off,styled}:{off:boolean;styled:boolean}){
  return <View style={{width:20,height:16,alignItems:"center",justifyContent:"center"}}>
    <View {...{className:styled?"border-text":""}} style={{width:18,height:11,borderWidth:border[2],borderRadius:radius[9],alignItems:"center",justifyContent:"center"}}>
      <View {...{className:styled?"bg-text":""}} style={{width:5,height:5,borderRadius:radius[3]}}/>
    </View>
    {off?<View {...{className:styled?"bg-text":""}} style={{position:"absolute",width:22,height:2,transform:[{rotate:"-35deg"}]}}/>:null}
  </View>;
}
function Letter({ch,styled}:{ch:string;styled:boolean}){
  return <Text {...{className:joinClasses(styled&&"text-text font-semibold")}}>{ch}</Text>;
}
function Chevron({up,styled}:{up:boolean;styled:boolean}){
  return <View {...{className:styled?(up?"border-b-text":"border-t-text"):""}} style={{width:0,height:0,borderLeftWidth:tokens.border7,borderRightWidth:tokens.border7,
    borderLeftColor:"transparent",borderRightColor:"transparent",...(up?{borderBottomWidth:tokens.border9}:{borderTopWidth:tokens.border9})}}/>;
}

function NameField({track,onRename,disabled,styled}:{track:TimelineTrack;onRename:(id:string,name:string)=>void;disabled:boolean;styled:boolean}){
  const [draft,store]=useLocalStore(()=>track.label);
  const editing=useRef(false);
  const dirty=useRef(false);
  // A rename from elsewhere (undo, another view) replaces the draft unless the user is typing.
  useEffect(()=>{if(!editing.current)store.set(track.label);},[track.label,store]);
  const commit=()=>{
    editing.current=false;
    if(!dirty.current)return;
    dirty.current=false;
    const name=store.get().trim();
    if(!name){store.set(track.label);return;}
    if(name!==track.label)onRename(track.id,name);
  };
  return <TextInput value={draft} editable={!disabled} accessibilityLabel={`Name of ${TRACK_KIND_LABEL[track.kind].toLowerCase()} track ${track.label}`}
    onFocus={()=>{editing.current=true;}} onChangeText={t=>{dirty.current=true;store.set(t);}} onSubmitEditing={commit} onBlur={commit}
    onKeyPress={e=>{if(e.nativeEvent.key==="Escape"){editing.current=false;dirty.current=false;store.set(track.label);}}}
    {...{className:joinClasses(styled&&"rounded-control text-text text-sm font-semibold px-1 focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{minHeight:28,minWidth:0,flexShrink:1,paddingVertical:space[0.5]}}/>;
}

/**
 * Track headers (D-18): one row per track, the height of its lane. Each row
 * has the track's name (edit in place; Enter or leaving the field renames,
 * Escape restores), its kind, and 44pt switches: lock on every track, hide
 * on video and overlay tracks, mute and solo on audio tracks. Solo silences
 * every audio track that is not soloed, and the header says so. In `reorder`
 * mode the switches give way to move up and move down buttons.
 */
export function TrackHeaders({scope='TrackHeaders',revision=0,...props}:TrackHeadersProps){
 const parent=useContext(EditorInteractionScope),owner=JSON.stringify(controlIdentity(scope,revision));
 const signature=useIdentityMemo(()=>timelineEditSignature(props.tracks),[props.tracks]);
 const boundary=useEditorBoundary([owner,parent,props.disabledReason,props.disabled,signature,props.laneHeight,props.compact,props.reorder]);
 const guard=useScopedControl(boundary,props,props.disabledReason!==undefined||!!props.disabled);
 return <EditorInteractionScope.Provider value={boundary}><TrackHeadersBody key={owner} {...props} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onSetFlag={(id,flag,value)=>guard.run('onSetFlag',host=>host.onSetFlag(id,flag,value))}
  onRename={(id,name)=>guard.run('onRename',host=>host.onRename(id,name))}
  {...(props.onMove?{onMove:(id:Parameters<NonNullable<TrackHeadersProps['onMove']>>[0],index:Parameters<NonNullable<TrackHeadersProps['onMove']>>[1])=>guard.run('onMove',host=>host.onMove?.(id,index))}:{})}
  {...(props.onOpenTrack?{onOpenTrack:(value:Parameters<NonNullable<TrackHeadersProps['onOpenTrack']>>[0])=>guard.current()?.onOpenTrack?.(value)}:{})}/></EditorInteractionScope.Provider>;
}
function TrackHeadersBody({
 actionError=null,disabledReason,
  tracks,laneHeight=56,onSetFlag,onRename,onMove,moveTarget,reorder=false,compact=false,openTrackId,onOpenTrack,allTracks,width=compact?56:232,disabled=false,
  className,unstyled=false,testID,style,...rest
}:TrackHeadersProps&{actionError?:string|null}){
  if(!Number.isFinite(laneHeight)||laneHeight<44)throw new RangeError("laneHeight must be at least 44");
  const styled=!unstyled;
  const target=moveTarget??((id:string,d:-1|1)=>{const i=tracks.findIndex(t=>t.id===id);const j=i+d;return i<0||j<0||j>=tracks.length?undefined:j;});
  const id=(s:string)=>testID?{testID:testID+"-"+s}:{};
  return <View {...rest} {...(testID?{testID}:{})} accessibilityRole="list" accessibilityLabel="Track headers"
    {...{className:joinClasses(className)}} style={[{width},style]}>
    <ErrorMessage message={actionError??undefined} unstyled={unstyled}/>
    {tracks.map(track=>{
      const silenced=trackSilenced(track,allTracks??tracks);
      const soloedAway=track.kind==="audio"&&!track.muted&&silenced;
      const status=track.locked?"Locked":soloedAway?"Silent: another track is soloed":silenced?(track.kind==="audio"?"Muted":"Hidden"):TRACK_KIND_LABEL[track.kind];
      const flagButton=(flag:TrackFlag)=>{
        const on=track[flag]===true;
        const label={locked:on?"Unlock":"Lock",hidden:on?"Show":"Hide",muted:on?"Unmute":"Mute",solo:on?"Unsolo":"Solo"}[flag];
        const icon=flag==="locked"?<LockGlyph open={!on} styled={styled}/>:flag==="hidden"?<EyeGlyph off={on} styled={styled}/>
          :<Letter ch={flag==="muted"?"M":"S"} styled={styled}/>;
        return <IconButton key={flag} size="sm" variant="ghost" selected={on} disabled={disabled} unstyled={unstyled}
          aria-label={`${label} ${track.label}`} icon={icon} onPress={()=>onSetFlag(track.id,flag,!on)} {...id(track.id+"-"+flag)}/>;
      };
      if(compact){
        const open=track.id===openTrackId;
        const marks=[track.locked&&"locked",track.hidden&&"hidden",track.muted&&"muted",track.solo&&"solo"].filter(Boolean).join(", ");
        return <View key={track.id} {...{className:joinClasses(styled&&"bg-surface-raised border-b border-border")}}
          style={{height:laneHeight,alignItems:"center",justifyContent:"center"}}>
          <Pressable accessibilityRole="button" accessibilityLabel={`${track.label} track settings${marks?", "+marks:""}`}
            accessibilityState={{expanded:open,disabled}} aria-expanded={open} disabled={disabled}
            onPress={()=>onOpenTrack?.(open?undefined:track.id)} {...id(track.id+"-open")}
            {...{className:joinClasses(styled&&"rounded-control border focus-visible:ring-2 focus-visible:ring-focus",
              styled&&(open?"border-focus bg-surface-sunken":"border-transparent"))}}
            style={{width:44,minHeight:size.touch,alignItems:"center",justifyContent:"center",gap:space[0.25]}}>
            <Text {...{className:joinClasses(styled&&"text-text text-sm font-semibold")}}>{trackCode(track,tracks)}</Text>
            {status!==TRACK_KIND_LABEL[track.kind]?<Text {...{className:joinClasses(styled&&"text-text-muted text-xs")}}>
              {track.locked?"Locked":silenced?(track.kind==="audio"?"Silent":"Hidden"):""}</Text>:null}
          </Pressable>
        </View>;
      }
      const up=target(track.id,-1),down=target(track.id,1);
      return <View key={track.id} accessibilityLabel={`${track.label}, ${status}`}
        {...{className:joinClasses(styled&&"bg-surface-raised border-b border-border")}}
        style={{height:laneHeight,flexDirection:"row",alignItems:"center",gap:space[1],paddingStart:space[2],paddingEnd:space[0.5]}}>
        <View style={{flex:1,minWidth:0,gap:space[0.25]}}>
          <NameField track={track} onRename={onRename} disabled={disabled} styled={styled}/>
          <Text numberOfLines={1} {...{className:joinClasses(styled&&"text-text-muted text-xs px-1")}}>{status}</Text>
        </View>
        {reorder&&onMove?<>
          <IconButton size="sm" variant="ghost" disabled={disabled||up===undefined} unstyled={unstyled} aria-label={`Move ${track.label} up`}
            icon={<Chevron up styled={styled}/>} onPress={()=>{if(up!==undefined)onMove(track.id,up);}} {...id(track.id+"-up")}/>
          <IconButton size="sm" variant="ghost" disabled={disabled||down===undefined} unstyled={unstyled} aria-label={`Move ${track.label} down`}
            icon={<Chevron up={false} styled={styled}/>} onPress={()=>{if(down!==undefined)onMove(track.id,down);}} {...id(track.id+"-down")}/>
        </>:trackFlags(track.kind).map(flagButton)}
      </View>;
    })}
  </View>;
}

import type {TimelineTrack} from '@/components/nyc-tron/ui/components/forge/timeline/edits';
/** Bounded geometry/permission identity; a playback clock tick is not an edit. */
export function timelineEditSignature(tracks:readonly TimelineTrack[]):string{
 if(tracks.length>1000)throw new RangeError('Too many timeline tracks');
 const trackIds=new Set<string>(),clipIds=new Set<string>();let count=0;
 for(const track of tracks){
  if(!track.id.trim()||track.id.length>512||trackIds.has(track.id)||track.label.length>1024||!['video','overlay','audio'].includes(track.kind))throw new RangeError('Invalid timeline track');trackIds.add(track.id);
  count+=track.clips.length;if(count>50000)throw new RangeError('Too many timeline clips');
  for(const clip of track.clips){
   if(!clip.id.trim()||clip.id.length>512||clipIds.has(clip.id)||!Number.isSafeInteger(clip.startFrame)||clip.startFrame<0||![clip.sourceIn,clip.sourceOut,clip.speed].every(Number.isFinite)||clip.sourceIn<0||clip.sourceOut<=clip.sourceIn||clip.speed<=0||clip.sourceDuration!==undefined&&(!Number.isFinite(clip.sourceDuration)||clip.sourceDuration<clip.sourceOut))throw new RangeError('Invalid timeline clip');clipIds.add(clip.id);
  }
 }
 return JSON.stringify(tracks.map(t=>[t.id,t.kind,t.locked,t.hidden,t.muted,t.solo,t.clips.map(c=>[c.id,c.startFrame,c.sourceIn,c.sourceOut,c.speed,c.sourceDuration])]));
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}

